// 읽기 끝 → 본문 맨 위로. 페이지 스크롤과 본문 스크롤 양쪽을 다 올린다
//  (기기·화면에 따라 스크롤 주체가 달라서 한쪽만 올리면 그대로 남아 있는 경우가 있다)
function rdToTop(){
  try{ window.scrollTo({top:0,behavior:"smooth"}); }catch(e){ window.scrollTo(0,0); }
  const b=$("rrBody"); if(b && b.scrollTop) { try{ b.scrollTo({top:0,behavior:"smooth"}); }catch(e){ b.scrollTop=0; } }
  const sc=document.querySelector("#rdRead"); if(sc && sc.scrollTop){ try{ sc.scrollTo({top:0,behavior:"smooth"}); }catch(e){ sc.scrollTop=0; } }
}
